const ANNEX_A = {impact:'A.5', lifecycle:'A.6', data:'A.7', transparency:'A.8', human_oversight:'A.9', third_party:'A.10'};
const HIGH_DOMAINS = ['credit','employment','insurance','healthcare'];
const TIERS = ['prohibited','high','limited','minimal'];
const f = $('AI Intake Form').first().json;
const raw = String($input.item.json.text || '');
let r;
try { r = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch (e) { return { json: { status: 'NEEDS_REVIEW', reason: 'LLM output not parseable', raw, intake: f } }; }
if (!TIERS.includes(r.eu_ai_act_tier)) { return { json: { status: 'NEEDS_REVIEW', reason: 'invalid or missing tier', raw, intake: f } }; }
r.control_themes = (Array.isArray(r.control_themes) ? r.control_themes : []).filter(t => ANNEX_A[t]);

// Overrides: change the tier or force review
const overrides = [];
if (f.affects_individuals === 'Yes' && HIGH_DOMAINS.includes(f.domain) && !['high','prohibited'].includes(r.eu_ai_act_tier)) {
  r.eu_ai_act_tier = 'high'; overrides.push('Rule: individual-impacting decision in Annex III-type domain');
}
if (f.human_in_loop === 'No') {
  if (!r.control_themes.includes('human_oversight')) r.control_themes.push('human_oversight');
  overrides.push('Rule: no human in loop');
}

// Additions: add control themes without forcing review
const additions = [];
if (['vendor SaaS','GenAI API'].includes(f.model_source) && !r.control_themes.includes('third_party')) {
  r.control_themes.push('third_party'); additions.push('Rule: externally hosted model');
}
if ((f.data_types || []).some(d => ['PII','PHI','financial'].includes(d)) && !r.control_themes.includes('data')) {
  r.control_themes.push('data'); additions.push('Rule: sensitive data declared');
}

r.iso42001_annex_a = [...new Set(r.control_themes.map(t => ANNEX_A[t]))];
const status = (r.confidence === 'low' || overrides.length || ['high','prohibited'].includes(r.eu_ai_act_tier)) ? 'NEEDS_REVIEW' : 'CLASSIFIED';
return { json: { status, overrides, additions, ...r, intake: f, note: 'Triage signal, not a legal determination' } };

// ==== CONFIG: edit these three values ====
const DATABASE_ID = 'PASTE_DATABASE_ID_HERE';     // printed by notion/create_register_db.sh
const CLASSIFIER_MODEL = 'llama3.2:3b';          // must match the model in the Chat Model node
const PROMPT_VERSION = 'v1';                      // bump whenever you change the Classify prompt
// ==========================================
const r = $input.first().json;
const f = r.intake || {};
const rawLLM = String($('Classify Use Case').first().json.text || r.raw || '');
const txt = s => [{ type: 'text', text: { content: String(s ?? '').slice(0, 2000) } }];
const list = a => (Array.isArray(a) && a.length ? a.map(x => '• ' + x).join('\n') : '');
const opt = v => (v ? { select: { name: String(v) } } : undefined);
const multi = a => ({ multi_select: (Array.isArray(a) ? a : []).filter(Boolean).map(x => ({ name: String(x) })) });
const rmf = [...new Set((r.nist_rmf_focus || []).map(x => String(x.function || '').toUpperCase()).filter(x => ['GOVERN','MAP','MEASURE','MANAGE'].includes(x)))];

const properties = {
  'Use Case': { title: txt(f.use_case || '(untitled)') },
  'Status': opt(r.status),
  'EU AI Act Tier': opt(r.eu_ai_act_tier || 'unknown'),
  'Confidence': opt(r.confidence),
  'Review Decision': opt(r.status === 'NEEDS_REVIEW' ? 'Pending' : null),
  'Tier Rationale': { rich_text: txt(r.tier_rationale) },
  'Domain': opt(f.domain),
  'Business Owner': { rich_text: txt(f.business_owner) },
  'Model Source': opt(f.model_source),
  'User Facing': opt(f.user_facing),
  'Affects Individuals': opt(f.affects_individuals),
  'Human in Loop': opt(f.human_in_loop),
  'Data Types': multi(f.data_types),
  'Control Themes': multi(r.control_themes),
  'ISO 42001 Annex A': multi(r.iso42001_annex_a),
  'NIST AI RMF Focus': multi(rmf),
  'Key Risks': { rich_text: txt(list(r.key_risks)) },
  'Open Questions': { rich_text: txt(list(r.open_questions)) },
  'Overrides': { rich_text: txt(list(r.overrides)) },
  'Rule Additions': { rich_text: txt(list(r.additions)) },
  'Error': { rich_text: txt(r.reason || '') },
  'Submitted At': f.submittedAt ? { date: { start: f.submittedAt } } : undefined,
  'Classifier Model': { rich_text: txt(CLASSIFIER_MODEL) },
  'Prompt Version': { rich_text: txt(PROMPT_VERSION) },
  'n8n Execution ID': { rich_text: txt($execution.id) },
  'Raw LLM Output': { rich_text: txt(rawLLM) },
};
Object.keys(properties).forEach(k => properties[k] === undefined && delete properties[k]);

const children = [
  { object: 'block', type: 'callout', callout: { icon: { emoji: '⚠️' }, rich_text: txt('Automated triage signal, not a legal determination. ' + (r.note || '')) } },
  { object: 'block', type: 'heading_3', heading_3: { rich_text: txt('Description (as submitted)') } },
  { object: 'block', type: 'paragraph', paragraph: { rich_text: txt(f.description) } },
];
return [{ json: { notionBody: { parent: { database_id: DATABASE_ID }, properties, children } } }];
